async function submit(name,v,el){const s=state(),p=D.app.plan;
 switch(name){case'profile':s.profile=v;break;
 case'zone':{const z=s.zones.find(z=>z.id===v.id);Object.assign(z,v);break;}
 case'compare':{const current={id:'current',name:'当前方案',plan:copy(p),document:doc(),metrics:C.metrics(p,regions(),s),image:await capture()},get=id=>id==='current'?current:snapshots.get(id);const a=get(v.a),b=get(v.b);if(!a||!b)throw Error('请选择有效快照');compareResult={a,b};diff=C.diffPlans(a.plan,b.plan);drawOverlay();render();return;}
 case'merge':{const choices={};mergeDraft.result.conflicts.forEach((c,i)=>choices[c.path]=v['conflict'+i]);const result=C.mergePlans(mergeDraft.base,mergeDraft.local,mergeDraft.incoming,choices);validateDocument(result.plan);await takeSnapshot('合并前自动备份');D.replacePlan(result.plan);mergeDraft=null;threeSig='';render();notice('合并已应用，原方案已自动保存为快照');return;}
 case'model':{const m=s.models.find(x=>x.id===v.id);Object.assign(m,v);for(const f of p.furniture.filter(f=>f.hpdModel===m.id))Object.assign(f,{w:m.w,d:m.d,h:m.h,price:m.price});break;}
 case'material':if(!v.name.trim())throw Error('请填写材料名称');s.materials.push({id:C.uid(),...v});break;
 case'cap':s.cap=v.cap;break;
 case'extra-cost':if(!v.name.trim())throw Error('请填写费用项目名称');s.extraCosts.push({id:'extra:'+C.uid(),...v});break;
 case'environment':s.environment={...s.environment,...v};p.site={...(p.site||{}),city:'自定义纬度',lat:v.latitude,month:v.month};p.north=v.north;D.S3.lighting.time=v.hour;D.S3.setLighting();break;
 case'cabinet':{const f=p.furniture.find(x=>x.id===v.id),map={层板:'door',挂衣:'hang',抽屉:'drawer',开放:'open'},cols=v.cols.split(/[,，]/).map(x=>map[x.trim()]||x.trim());if(!cols.length||cols.length>16||cols.some(x=>!['door','hang','drawer','open'].includes(x)))throw Error('柜格仅支持层板、挂衣、抽屉、开放，最多16格');Object.assign(f,{w:v.w,d:v.d,h:v.h});f.cab={...f.cab,cols,door:v.door};break;}
 case'sections':s.sections=v;break;
 case'obstruction':s.environment.obstructions||=[];s.environment.obstructions.push({id:C.uid(),...v});break;
 case'schedule':if(s.tasks.some(t=>t.template))throw Error('已生成模板计划，请编辑现有任务，避免重复追加');s.tasks.push(...C.schedule(C.costRows(p,regions(),s),v.start).map(t=>({...t,template:true})));break;
 case'task':if(!v.name.trim())throw Error('请填写任务名称');if(v.start&&v.end&&v.start>v.end)throw Error('截止日期不能早于开始日期');s.tasks.push({id:C.uid(),...v,status:'待开始'});break;
 case'note':{if(!v.text.trim())throw Error('请填写批注内容');const target=p.furniture.find(f=>f.id===D.app.sel.id)||p.elec.find(e=>e.id===D.app.sel.id)||p.rooms.find(r=>r.id===D.app.sel.id),r=$('#c2d').getBoundingClientRect(),point=target?{x:target.x,y:target.y}:{x:(r.width/2-D.view.ox)/D.view.s,y:(r.height/2-D.view.oy)/D.view.s};const a=await saveAsset({id:C.uid(),projectId:s.projectId,name:'批注截图',kind:'note-image',type:'image/jpeg',data:await capture()});s.notes.push({id:C.uid(),...v,target:D.app.sel.id,point,image:a.id,updated:Date.now()});break;}
 case'evidence':if(!v.name.trim())throw Error('请填写对象名称');s.evidence.push({id:C.uid(),...v});break;
 case'dimension':if(!v.name.trim())throw Error('请填写尺寸名称');s.dimensions.push({id:C.uid(),...v});break;
 default:throw Error('未实现表单：'+name);
 }commit();render();drawOverlay();await syncThree();notice('已更新当前方案');}
async function change(el){const s=state();if(el.dataset.storage){const id=el.dataset.storage,key=el.dataset.key,v=el.type==='number'?el.valueAsNumber:el.value;if(el.type==='number'&&(!Number.isFinite(v)||v<0))throw Error('收纳数量需为非负数');s.storage[id]||={};s.storage[id][key]=v;commit();render();return;}
 if(el.dataset.cost){const id=el.dataset.cost,key=el.dataset.key;s.costs[id]||={};if(key==='material'){const m=s.materials.find(m=>m.id===el.value);s.costs[id].material=el.value;if(m)s.costs[id].price=m.price;}else{const n=el.valueAsNumber;if(!Number.isFinite(n)||n<0)throw Error('费用请输入非负数');s.costs[id][key]=n;}commit();render();return;}
 if(el.dataset.task){const t=s.tasks.find(t=>t.id===el.dataset.task),key=el.dataset.key;if((key==='start'&&t.end&&el.value>t.end)||(key==='end'&&t.start&&el.value<t.start))throw Error('任务截止日期不能早于开始日期');t[key]=el.value;t.updated=Date.now();commit();return;}
 if(el.type!=='file'||!el.files.length)return;const files=[...el.files];if(files.reduce((s,f)=>s+f.size,0)>80*1024*1024)throw Error('单次文件总量请控制在 80 MB 内');
 if(el.id==='hpd-model-file'){const mains=files.filter(f=>/\.(glb|gltf)$/i.test(f.name));if(mains.length!==1)throw Error('每次请选择一个 GLB 或 glTF 主文件，以及它的配套文件');const saved=[];for(const f of files)saved.push(await saveAsset(await fileAsset(f,'model')));const main=saved.find(a=>a.name===mains[0].name),m={id:C.uid(),name:main.name.replace(/\.(glb|gltf)$/i,''),asset:main.id,files:saved.filter(a=>a.id!==main.id).map(a=>a.id),w:1000,d:600,h:800,price:0,sku:''};await parseModel(m);s.models.push(m);commit();render();notice('模型已解析，可设置实际尺寸后添加到方案');}
 else if(el.id==='hpd-texture-file'){const f=files[0];if(!/^image\/(png|jpeg|webp)$/.test(f.type))throw Error('贴图仅支持 PNG、JPEG、WebP');const a=await saveAsset(await fileAsset(f,'texture'));s.materials.push({id:C.uid(),name:f.name,category:'地面',asset:a.id,price:0,unit:'㎡',palette:'自定义',sku:'',repeat:600});commit();render();notice('贴图已加入材料库，可在开放分区应用');}
 else if(el.id==='hpd-package-file'||el.id==='hpd-compare-file'){await importPackage(JSON.parse(await files[0].text()),el.id==='hpd-package-file');}
 else if(el.id==='hpd-notes-file'){const pack=JSON.parse(await files[0].text());if(pack.format!=='hpd-notes'||pack.projectId!==s.projectId)throw Error('批注包不是当前项目，未合并');for(const a of pack.assets||[])if(/^data:image\/(png|jpeg|webp);base64,/.test(a.data))await saveAsset(a);let count=0;for(const n of pack.notes||[]){if(!n.id||!n.text||!['待处理','处理中','已解决'].includes(n.status))throw Error('批注包包含无效记录');const old=s.notes.find(x=>x.id===n.id);if(!old){s.notes.push(n);count++;}else if(n.updated>old.updated){Object.assign(old,n);count++;}else if(n.updated===old.updated&&JSON.stringify(n)!==JSON.stringify(old)){s.notes.push({...n,id:C.uid(),text:'[并行修改] '+n.text});count++;}}commit();render();notice(`合并 ${count} 条批注；同时间冲突另存记录`);}
 else if(el.id.startsWith('hpd-task-photo-')){const t=s.tasks.find(t=>t.id===el.id.slice('hpd-task-photo-'.length)),f=files[0];if(!/^image\/(png|jpeg|webp)$/.test(f.type))throw Error('照片需为 PNG、JPEG、WebP');const a=await saveAsset(await fileAsset(f,'site-photo'));t.photo=a.id;t.updated=Date.now();commit();render();notice('验收照片已保存');}
 }
let initialPlan;
async function boot(){db=await openDB();for(const a of await dbCall('assets','readonly',s=>s.getAll()))assets.set(a.id,a);for(const sn of await dbCall('snapshots','readonly',s=>s.getAll()))snapshots.set(sn.id,sn);if(window.__HPD_BUNDLE__||window.__SHARED__?.assistant){const b=window.__HPD_BUNDLE__||window.__SHARED__.assistant;validateDocument(b.document);for(const a of b.assets||[])await saveAsset(a);for(const sn of b.snapshots||[]){await dbCall('snapshots','readwrite',s=>s.put(sn));snapshots.set(sn.id,sn);}if(window.__HPD_BUNDLE__&&!D.app.loadedFromLocal)D.replacePlan(copy(b.document));}state();C.identify(D.app.plan);initialPlan=copy(D.app.plan);const old=await dbCall('recovery','readonly',s=>s.get(state().projectId));if(old&&old.revision!==manifest.revision)previousRecovery=old;D.on('commit',()=>{C.identify(D.app.plan);clearTimeout(recoveryTimer);recoveryTimer=setTimeout(async()=>{try{const p=D.app.plan;await dbCall('recovery','readwrite',o=>o.put({id:state().projectId,revision:manifest.revision,updated:Date.now(),document:doc(),plan:copy(p),metrics:C.metrics(p,regions(),state())}));}catch(e){notice(e.message,true);}},1200);});rootUI();window.HPD={version:C.VERSION,state,show,render,commit,action,submit,assets,snapshots,projectPackage,importPackage,takeSnapshot,addModel,parseModel,syncThree,capture,initialPlan,lastError:'',get issues(){return issues;},get routes(){return routes;},get diff(){return diff;},get modelBindings(){return modelBindings;},ready:true};setInterval(()=>{drawOverlay();syncThree();},450);await syncThree();}
boot().catch(e=>{console.error('设计助手启动失败',e);notice(e.message,true);window.HPD={ready:false,lastError:e.message};});
